+        std::vector<size_t> offs_zero;
+        auto z4 = craft_zip({{"assets/zero.bin", {}, 0, {}, {}, false, false, 0, false}},
+                            0, &offs_zero);
+        const std::string p4 = dir + "/zero.zip";
+        write_file(p4, z4);
