+        LAW(ex == win, 42, "integ: extraction path == independent fd-window path");
+    }
+
+    std::printf("c9_zip_data_offset_law_test: %d/%d PASS\n", g_pass, g_pass + g_fail);
+    return g_fail == 0 ? 0 : 1;
+}
